import React, { useMemo } from "react";
import { AbsoluteFill, interpolate, spring, useCurrentFrame, useVideoConfig, random } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadSpaceGrotesk = makeLoadFont('SpaceGrotesk');

const { fontFamily: spaceGroteskFamily } = loadSpaceGrotesk();



export type GlowingMapProps = Record<string, any>;

const BackgroundGrid = ({ color, frame }: { color: string; frame: number }) => {
  const opacity = spring({ fps: 30, frame, config: { damping: 20 } });
  
  return (
    <svg width="100%" height="100%" style={{ position: 'absolute', zIndex: 0, opacity, transition: 'none' }}>
      <defs>
        <pattern id="gridPattern" width="80" height="80" patternUnits="userSpaceOnUse">
          <path d="M 80 0 L 0 0 0 80" fill="none" stroke={color} strokeWidth="1.5" opacity="0.1" />
        </pattern>
        <radialGradient id="gridMask" cx="50%" cy="50%" r="50%">
          <stop offset="20%" stopColor="white" stopOpacity="1" />
          <stop offset="90%" stopColor="white" stopOpacity="0" />
        </radialGradient>
      </defs>
      <mask id="gridFade">
        <rect width="100%" height="100%" fill="url(#gridMask)" />
      </mask>
      <rect width="100%" height="100%" fill="url(#gridPattern)" mask="url(#gridFade)" />
    </svg>
  );
};

const MapSilhouettes = ({ width, height, color, frame }: { width: number; height: number; color: string; frame: number }) => {
  const { fps } = useVideoConfig();
  const mapOpacity = spring({ fps, frame, config: { damping: 30 } }) * 0.15;
  const w = width;
  const h = height;

  return (
    <svg width="100%" height="100%" style={{ position: 'absolute', opacity: mapOpacity, transition: 'none', zIndex: 1 }}>
      <g stroke={color} strokeWidth={2} fill="none" strokeDasharray="4 6" strokeLinejoin="round">
        {/* North America Region */}
        <path d={`M ${w*0.15} ${h*0.2} L ${w*0.35} ${h*0.18} L ${w*0.4} ${h*0.3} L ${w*0.25} ${h*0.4} L ${w*0.12} ${h*0.35} Z`} />
        {/* South America Region */}
        <path d={`M ${w*0.25} ${h*0.45} L ${w*0.4} ${h*0.5} L ${w*0.35} ${h*0.75} L ${w*0.2} ${h*0.6} Z`} />
        {/* Europe & Asia Region */}
        <path d={`M ${w*0.48} ${h*0.2} L ${w*0.8} ${h*0.15} L ${w*0.98} ${h*0.35} L ${w*0.9} ${h*0.6} L ${w*0.7} ${h*0.55} L ${w*0.55} ${h*0.4} Z`} />
        {/* Africa Region */}
        <path d={`M ${w*0.45} ${h*0.42} L ${w*0.6} ${h*0.45} L ${w*0.58} ${h*0.68} L ${w*0.42} ${h*0.55} Z`} />
      </g>
    </svg>
  );
};

const Connection = ({ startNode, endNode, color, frame, delay, faint = false }: any) => {
  const { fps } = useVideoConfig();
  const dx = endNode.x - startNode.x;
  const dy = endNode.y - startNode.y;
  const distance = Math.sqrt(dx * dx + dy * dy);
  
  // Arch the paths upwards
  const midX = (startNode.x + endNode.x) / 2;
  const midY = (startNode.y + endNode.y) / 2 - distance * (faint ? 0.15 : 0.25);
  const pathD = `M ${startNode.x} ${startNode.y} Q ${midX} ${midY} ${endNode.x} ${endNode.y}`;

  const trackEnter = spring({ fps, frame: frame - delay, config: { damping: 20 } });
  
  const activeFrame = frame - delay;
  const t = activeFrame >= 0 ? activeFrame % 180 : -1;
  
  // Animate from 100 to -20 relative to pathLength="100" to allow the packet to travel and exit cleanly
  const offset = interpolate(t, [0, 80], [100, -20], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
  const packetOpacity = t >= 0 ? interpolate(t, [0, 5, 75, 80], [0, 1, 1, 0], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' }) : 0;

  return (
    <svg style={{ position: 'absolute', top: 0, left: 0, width: '100%', height: '100%', pointerEvents: 'none', zIndex: 5, transition: 'none' }}>
      {/* Track Base */}
      <path 
        d={pathD} 
        fill="none" 
        stroke={color} 
        strokeWidth={faint ? 1 : 2} 
        opacity={trackEnter * (faint ? 0.05 : 0.15)} 
        strokeDasharray="4 6" 
      />
      {/* Traveling Data Packet */}
      {t >= 0 && (
        <path
          d={pathD}
          fill="none"
          stroke={color}
          strokeWidth={faint ? 2 : 6}
          pathLength="100"
          strokeDasharray="20 100"
          strokeDashoffset={offset}
          strokeLinecap="round"
          style={{ 
            filter: `drop-shadow(0 0 ${faint ? 4 : 10}px ${color})`, 
            opacity: packetOpacity * (faint ? 0.4 : 1),
            transition: 'none'
          }}
        />
      )}
    </svg>
  );
};

const NetworkNode = ({ node, color, frame }: any) => {
  const { fps } = useVideoConfig();
  const entranceScale = spring({ fps, frame: frame - node.delay, config: { damping: 12 } });
  
  const activePulseFrame = Math.max(0, frame - node.delay);
  const pulseScale = interpolate(activePulseFrame % 90, [0, 90], [1, 2.8], { extrapolateRight: 'clamp' });
  const pulseOpacity = interpolate(activePulseFrame % 90, [0, 60, 90], [0.5, 0, 0], { extrapolateRight: 'clamp' });

  if (frame < node.delay) return null;

  return (
    <div style={{
      position: 'absolute',
      left: node.x,
      top: node.y,
      zIndex: node.isMain ? 20 : 10,
      transition: 'none'
    }}>
      <div style={{ transform: `scale(${entranceScale})`, transition: 'none' }}>
        {/* Expanding Pulse Ring */}
        {node.isMain && (
          <div style={{
            position: 'absolute',
            width: 50,
            height: 50,
            left: -25,
            top: -25,
            borderRadius: '50%',
            border: `2px solid ${color}`,
            opacity: pulseOpacity,
            transform: `scale(${pulseScale})`,
            transition: 'none'
          }} />
        )}
        
        {/* Core Dot */}
        <div style={{
          position: 'absolute',
          width: node.isMain ? 18 : 10,
          height: node.isMain ? 18 : 10,
          left: node.isMain ? -9 : -5,
          top: node.isMain ? -9 : -5,
          borderRadius: '50%',
          backgroundColor: '#ffffff',
          boxShadow: `0 0 20px 5px ${color}`,
          transition: 'none'
        }} />

        {/* Floating Label */}
        {node.isMain && (
          <div style={{
            position: 'absolute',
            top: 20,
            left: '50%',
            transform: 'translateX(-50%)',
            color: '#ffffff',
            fontSize: 26,
            fontWeight: 700,
            letterSpacing: 2,
            textShadow: `0 0 12px ${color}`,
            fontFamily: spaceGroteskFamily,
            whiteSpace: 'nowrap',
            opacity: 0.95,
            transition: 'none'
          }}>
            {node.label}
          </div>
        )}
      </div>
    </div>
  );
};

const FloatingParticles = ({ count, width, height, frame, color }: any) => {
  const particles = useMemo(() => {
    return Array.from({ length: count }).map((_, i) => ({
      x: random(`px-${i}`) * width,
      yStart: random(`py-${i}`) * height,
      speed: random(`pspeed-${i}`) * 2 + 1,
      size: random(`psize-${i}`) * 3 + 1,
      blinkSpeed: random(`pblink-${i}`) * 0.05 + 0.02,
    }));
  }, [count, width, height]);

  return (
    <>
      {particles.map((p, i) => {
        const y = (p.yStart - frame * p.speed) % height;
        const finalY = y < 0 ? y + height : y;
        const opacity = (Math.sin(frame * p.blinkSpeed + i) + 1) / 2 * 0.6;

        return (
          <div
            key={i}
            style={{
              position: 'absolute',
              left: p.x,
              top: finalY,
              width: p.size,
              height: p.size,
              backgroundColor: color,
              borderRadius: '50%',
              opacity,
              boxShadow: `0 0 ${p.size * 2}px ${color}`,
              zIndex: 2,
              transition: 'none'
            }}
          />
        );
      })}
    </>
  );
};

const CinematicLighting = ({ color1, color2 }: { color1: string; color2: string }) => (
  <svg width="100%" height="100%" style={{ position: 'absolute', pointerEvents: 'none', zIndex: 0, transition: 'none' }}>
    <defs>
      <radialGradient id="orbTopLeft">
        <stop offset="0%" stopColor={color1} stopOpacity="0.2" />
        <stop offset="100%" stopColor={color1} stopOpacity="0" />
      </radialGradient>
      <radialGradient id="orbBottomRight">
        <stop offset="0%" stopColor={color2} stopOpacity="0.15" />
        <stop offset="100%" stopColor={color2} stopOpacity="0" />
      </radialGradient>
    </defs>
    <circle cx="20%" cy="30%" r="50%" fill="url(#orbTopLeft)" />
    <circle cx="80%" cy="70%" r="50%" fill="url(#orbBottomRight)" />
  </svg>
);

const HUDOverlay = ({ frame, colorPrimary, colorSecondary }: any) => {
  const hexValues = Array.from({ length: 4 }).map((_, i) =>
    Math.floor(random(`hex-${i}-${Math.floor(frame / 6)}`) * 16777215)
      .toString(16)
      .padStart(6, '0')
      .toUpperCase()
  ).join(' : ');

  return (
    <div style={{ position: 'absolute', inset: 0, pointerEvents: 'none', zIndex: 50, transition: 'none' }}>
      <div style={{ position: 'absolute', top: 60, left: 40, color: colorPrimary, fontFamily: spaceGroteskFamily, fontSize: 16, opacity: 0.8, letterSpacing: 2 }}>
        GLOBAL COMMS LINK ACTIVE<br/>
        ENCRYPTION LEVEL: SECURE
      </div>
      <div style={{ position: 'absolute', bottom: 80, right: 40, color: colorSecondary, fontFamily: spaceGroteskFamily, fontSize: 16, opacity: 0.8, textAlign: 'right', letterSpacing: 1 }}>
        NODE PACKET TRANSFER<br/>
        {hexValues}
      </div>
    </div>
  );
};

export const GlowingMap: React.FC<GlowingMapProps> = ({
  backgroundColor = "#030014",
  transparentBackground = false,
  durationInSeconds = 12,
  neonPrimary = "#00ffff",
  neonSecondary = "#ff00aa",
  neonAccent = "#ffaa00",
  particleCount = 60,
}) => {
  const frame = useCurrentFrame();
  const { width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;
  
  const colors: Record<string, string> = { neonPrimary, neonSecondary, neonAccent };

  const nodes = useMemo(() => [
    { id: 'US', label: 'UNITED STATES', x: width * 0.22, y: height * 0.35, isMain: true, delay: 10, colorKey: 'neonPrimary' },
    { id: 'UK', label: '', x: width * 0.52, y: height * 0.30, isMain: false, delay: 20, colorKey: 'neonPrimary' },
    { id: 'TR', label: 'TURKEY', x: width * 0.62, y: height * 0.45, isMain: true, delay: 40, colorKey: 'neonSecondary' },
    { id: 'IR', label: 'IRAN', x: width * 0.72, y: height * 0.52, isMain: true, delay: 65, colorKey: 'neonAccent' },
    { id: 'PK', label: 'PAKISTAN', x: width * 0.85, y: height * 0.60, isMain: true, delay: 90, colorKey: 'neonPrimary' },
    { id: 'BR', label: '', x: width * 0.30, y: height * 0.65, isMain: false, delay: 55, colorKey: 'neonSecondary' },
    { id: 'SG', label: '', x: width * 0.90, y: height * 0.75, isMain: false, delay: 110, colorKey: 'neonAccent' },
  ], [width, height]);

  const routes = useMemo(() => [
    // Primary Comm Routes
    { startId: 'US', endId: 'TR', delay: 45, colorKey: 'neonPrimary' },
    { startId: 'TR', endId: 'IR', delay: 70, colorKey: 'neonSecondary' },
    { startId: 'IR', endId: 'PK', delay: 95, colorKey: 'neonAccent' },
    { startId: 'US', endId: 'PK', delay: 115, colorKey: 'neonPrimary' },
    { startId: 'PK', endId: 'TR', delay: 145, colorKey: 'neonSecondary' },
    { startId: 'TR', endId: 'US', delay: 165, colorKey: 'neonAccent' },
    // Faint Background Comm Routes
    { startId: 'UK', endId: 'TR', delay: 50, colorKey: 'neonPrimary', faint: true },
    { startId: 'US', endId: 'BR', delay: 60, colorKey: 'neonSecondary', faint: true },
    { startId: 'PK', endId: 'SG', delay: 125, colorKey: 'neonAccent', faint: true },
  ], []);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: 'hidden' }}>
      
      {/* 1. Cinematic Lighting Orbs */}
      <CinematicLighting color1={neonPrimary} color2={neonSecondary} />
      
      {/* 2. Background Digital Grid */}
      <BackgroundGrid color={neonPrimary} frame={frame} />
      
      {/* 3. Floating Environment Particles */}
      <FloatingParticles count={particleCount} width={width} height={height} frame={frame} color={neonPrimary} />

      {/* 4. Map Region Silhouettes */}
      <MapSilhouettes width={width} height={height} color={neonAccent} frame={frame} />

      {/* 5. Communication Links */}
      {routes.map((route, idx) => {
        const startNode = nodes.find(n => n.id === route.startId);
        const endNode = nodes.find(n => n.id === route.endId);
        if (!startNode || !endNode) return null;
        
        return (
          <Connection 
            key={`route-${idx}`} 
            startNode={startNode} 
            endNode={endNode} 
            color={colors[route.colorKey]} 
            frame={frame} 
            delay={route.delay} 
            faint={route.faint} 
          />
        );
      })}

      {/* 6. Network Nodes */}
      {nodes.map((node) => (
        <NetworkNode 
          key={node.id} 
          node={node} 
          color={colors[node.colorKey]} 
          frame={frame} 
        />
      ))}

      {/* 7. Vignette for Depth */}
      <div style={{
        position: 'absolute', inset: 0, pointerEvents: 'none', zIndex: 30, transition: 'none',
        background: 'radial-gradient(circle, transparent 40%, rgba(0,0,0,0.85) 100%)'
      }} />

      {/* 8. Digital HUD Details */}
      <HUDOverlay frame={frame} colorPrimary={neonPrimary} colorSecondary={neonSecondary} />

    </AbsoluteFill>
  );
};

export default GlowingMap;